package com.fuelflex.platform.operations.controller;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import com.fuelflex.platform.operations.dto.InternalConsumptionDtos.*;import com.fuelflex.platform.operations.service.InternalConsumptionService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;
@RestController@RequestMapping("/api/v1")@RequiredArgsConstructor public class InternalConsumptionController{private final InternalConsumptionService service;@PostMapping("/manager/shift-assignments/{id}/internal-consumptions")@ResponseStatus(HttpStatus.CREATED)@PreAuthorize("hasAuthority('MANAGER') and hasAuthority('internal-consumption:create')")public Response create(@PathVariable UUID id,@Valid@RequestBody CreateRequest r){return service.create(id,r);}@GetMapping("/manager/shift-assignments/{id}/internal-consumptions")@PreAuthorize("hasAuthority('MANAGER') and hasAuthority('internal-consumption:view')")public List<Response>managerShift(@PathVariable UUID id){return service.byShift(id);}@GetMapping("/manager/operational-days/{id}/internal-consumptions")@PreAuthorize("hasAuthority('MANAGER') and hasAuthority('internal-consumption:view')")public List<Response>managerDay(@PathVariable UUID id){return service.byDay(id);}@GetMapping("/supervisor/shift-assignments/{id}/internal-consumptions")@PreAuthorize("hasAuthority('SUPERVISOR') and hasAuthority('internal-consumption:view')")public List<Response>supervisorShift(@PathVariable UUID id){return service.byShift(id);}@GetMapping("/supervisor/operational-days/{id}/internal-consumptions")@PreAuthorize("hasAuthority('SUPERVISOR') and hasAuthority('internal-consumption:view')")public List<Response>supervisorDay(@PathVariable UUID id){return service.byDay(id);}}
